use clap::{Parser, Subcommand};
use std::path::PathBuf;

mod cli;
mod lints;
mod parser;
mod fixer;
mod config;
mod reporter;

use cli::{CheckArgs, FixArgs, SingleArgs};

#[derive(Parser)]
#[command(name = "statix")]
#[command(about = "Lints and suggestions for the Nix programming language")]
#[command(version = "0.5.8")]
#[command(author = "Akshay <nerdy@peppe.rs>")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Lints and suggestions for the nix programming language
    Check(CheckArgs),
    /// Find and fix issues raised by statix-check
    Fix(FixArgs),
    /// Fix exactly one issue at provided position
    Single(SingleArgs),
    /// List all available lints
    List,
    /// Print detailed explanation for a lint warning
    Explain {
        /// Lint code (e.g., W01, W02)
        lint: String,
    },
    /// Dump a sample config to stdout
    Dump,
}

fn main() {
    let cli = Cli::parse();

    match cli.command {
        Commands::Check(args) => cli::check(args),
        Commands::Fix(args) => cli::fix(args),
        Commands::Single(args) => cli::single(args),
        Commands::List => lints::list_lints(),
        Commands::Explain { lint } => lints::explain_lint(&lint),
        Commands::Dump => config::dump_config(),
    }
}
EOFMAIN

