use clap::Parser;
use std::path::PathBuf;

#[derive(Parser, Debug)]
pub struct CheckArgs {
    /// File or directory to run check on
    #[arg(default_value = ".")]
    pub target: Option<String>,

    /// Path to statix.toml or its parent directory
    #[arg(short, long, default_value = ".")]
    pub config: String,

    /// Globs of file patterns to skip
    #[arg(short, long)]
    pub ignore: Vec<String>,

    /// Output format. Supported values: stderr, errfmt
    #[arg(short, long, default_value = "stderr")]
    pub format: String,

    /// Enable "streaming" mode, accept file on stdin, output diagnostics on stdout
    #[arg(short, long)]
    pub stdin: bool,

    /// Don't respect .gitignore files
    #[arg(short, long)]
    pub unrestricted: bool,
}

#[derive(Parser, Debug)]
pub struct FixArgs {
    /// File or directory to run fix on
    #[arg(default_value = ".")]
    pub target: Option<String>,

    /// Path to statix.toml or its parent directory
    #[arg(short, long, default_value = ".")]
    pub config: String,

    /// Globs of file patterns to skip
    #[arg(short, long)]
    pub ignore: Vec<String>,

    /// Do not fix files in place, display a diff instead
    #[arg(short, long)]
    pub dry_run: bool,

    /// Enable "streaming" mode, accept file on stdin, output diagnostics on stdout
    #[arg(short, long)]
    pub stdin: bool,

    /// Don't respect .gitignore files
    #[arg(short, long)]
    pub unrestricted: bool,
}

#[derive(Parser, Debug)]
pub struct SingleArgs {
    /// File to run single-fix on
    pub target: Option<String>,

    /// Position to attempt a fix at (format: line,col)
    #[arg(short, long)]
    pub position: String,

    /// Path to statix.toml or its parent directory
    #[arg(short, long, default_value = ".")]
    pub config: String,

    /// Do not fix files in place, display a diff instead
    #[arg(short, long)]
    pub dry_run: bool,

    /// Enable "streaming" mode, accept file on stdin, output diagnostics on stdout
    #[arg(short, long)]
    pub stdin: bool,
}

pub fn check(args: CheckArgs) {
    if args.stdin {
        crate::reporter::check_stdin(&args);
    } else {
        let target = args.target.unwrap_or_else(|| ".".to_string());
        crate::reporter::check_path(&target, &args);
    }
}

pub fn fix(args: FixArgs) {
    if args.stdin {
        crate::reporter::fix_stdin(&args);
    } else {
        let target = args.target.unwrap_or_else(|| ".".to_string());
        crate::reporter::fix_path(&target, &args);
    }
}

pub fn single(args: SingleArgs) {
    // Parse position
    let parts: Vec<&str> = args.position.split(',').collect();
    if parts.len() != 2 {
        eprintln!("error: Invalid value for '--position <POSITION>': unable to parse `{}` as line and column", args.position);
        std::process::exit(2);
    }

    crate::reporter::single_fix(args);
}
EOFCLI

