use std::collections::HashMap;

pub struct Lint {
    pub code: &'static str,
    pub name: &'static str,
    pub explanation: &'static str,
}

pub fn get_lints() -> HashMap<&'static str, Lint> {
    let mut map = HashMap::new();

    map.insert("W01", Lint {
        code: "W01",
        name: "bool_comparison",
        explanation: r#"## What it does
Checks for expressions of the form `x == true`, `x != true` and
suggests using the variable directly.

## Why is this bad?
Unnecessary code.

## Example
Instead of checking the value of `x`:

```nix
if x == true then 0 else 1
```

Use `x` directly:

```nix
if x then 0 else 1
```"#,
    });

    map.insert("W02", Lint {
        code: "W02",
        name: "empty_let_in",
        explanation: r#"## What it does
Checks for empty let-in expressions with no bindings.

## Why is this bad?
Unnecessary code.

## Example
Instead of:

```nix
let in expr
```

Use:

```nix
expr
```"#,
    });

    map.insert("W03", Lint {
        code: "W03",
        name: "manual_inherit",
        explanation: r#"## What it does
Checks for manual binding assignments that could use inherit.

## Why is this bad?
The inherit keyword is more concise.

## Example
Instead of:

```nix
let
  mtl = pkgs.haskellPackages.mtl;
in ...
```

Use:

```nix
let
  inherit (pkgs.haskellPackages) mtl;
in ...
```"#,
    });

    map.insert("W04", Lint {
        code: "W04",
        name: "manual_inherit_from",
        explanation: r#"## What it does
Checks for manual attribute set bindings that could use inherit.

## Why is this bad?
The inherit keyword is more concise.

## Example
Instead of:

```nix
{ mtl = pkgs.haskellPackages.mtl; }
```

Use:

```nix
{ inherit (pkgs.haskellPackages) mtl; }
```"#,
    });

    map.insert("W05", Lint {
        code: "W05",
        name: "legacy_let_syntax",
        explanation: r#"## What it does
Checks for legacy let syntax.

## Why is this bad?
Modern Nix uses different syntax.

## Example
Use modern syntax."#,
    });

    map.insert("W06", Lint {
        code: "W06",
        name: "collapsible_let_in",
        explanation: r#"## What it does
Checks for nested let-in expressions that could be collapsed.

## Why is this bad?
Unnecessary nesting.

## Example
Instead of:

```nix
let x = let y = 1; in y; in x
```

Collapse to simpler form."#,
    });

    map.insert("W07", Lint {
        code: "W07",
        name: "eta_reduction",
        explanation: r#"## What it does
Checks for functions that could be simplified through eta reduction.

## Why is this bad?
Unnecessary function wrapper.

## Example
Instead of:

```nix
f = x: f x;
```

Use:

```nix
f = f;
```"#,
    });

    map.insert("W08", Lint {
        code: "W08",
        name: "useless_parens",
        explanation: r#"## What it does
Checks for unnecessary parentheses.

## Why is this bad?
Unnecessary code.

## Example
Instead of:

```nix
x = (1 + 2);
```

Use:

```nix
x = 1 + 2;
```"#,
    });

    map.insert("W10", Lint {
        code: "W10",
        name: "empty_pattern",
        explanation: r#"## What it does
Checks for empty patterns.

## Why is this bad?
Unnecessary pattern.

## Example
Instead of:

```nix
{}: expr
```

Use:

```nix
_: expr
```"#,
    });

    map.insert("W11", Lint {
