    match parser::parse_nix(content) {
        Ok(ast) => {
            // Run lints
            let mut has_issues = false;

            // W01 - bool_comparison
            if let Some(issues) = lints::check_bool_comparison(&ast, content, filename) {
                for issue in issues {
                    report_issue(&issue, &args.format);
                    has_issues = true;
                }
            }

            // W02 - empty_let_in
            if let Some(issues) = lints::check_empty_let_in(&ast, content, filename) {
                for issue in issues {
                    report_issue(&issue, &args.format);
                    has_issues = true;
                }
            }

            // W08 - useless_parens
            if let Some(issues) = lints::check_useless_parens(&ast, content, filename) {
                for issue in issues {
                    report_issue(&issue, &args.format);
                    has_issues = true;
                }
            }

            // W14 - empty_inherit
            if let Some(issues) = lints::check_empty_inherit(&ast, content, filename) {
                for issue in issues {
                    report_issue(&issue, &args.format);
                    has_issues = true;
                }
            }

            if has_issues {
                std::process::exit(1);
            }
        }
        Err(e) => eprintln!("Error parsing {}: {}", filename, e),
    }
}

fn report_issue(issue: &lints::Issue, format: &str) {
    if format == "errfmt" {
        println!("{}>{},{}:W:{}:{}", issue.filename, issue.line, issue.column, issue.code, issue.message);
    } else {
        // stderr format with colors
        println!("{}", issue.format_for_stderr());
    }
}

pub fn fix_stdin(args: &FixArgs) {
    let mut content = String::new();
    io::stdin().read_to_string(&mut content).unwrap();

    match crate::fixer::fix_content(&content, "<stdin>", args) {
        Ok(fixed) => print!("{}", fixed),
        Err(e) => eprintln!("Error: {}", e),
    }
}

pub fn fix_path(path: &str, args: &FixArgs) {
    if Path::new(path).is_file() {
        match fs::read_to_string(path) {
            Ok(content) => {
                match crate::fixer::fix_content(&content, path, args) {
                    Ok(fixed) => {
                        if args.dry_run {
                            // Show diff
                            show_diff(&content, &fixed, path);
                        } else {
                            // Write file
                            if let Err(e) = fs::write(path, &fixed) {
                                eprintln!("Error writing file {}: {}", path, e);
                            }
                        }
                    }
                    Err(e) => eprintln!("Error: {}", e),
                }
            }
            Err(e) => eprintln!("Error reading file {}: {}", path, e),
        }
    } else {
        // Walk directory
        if let Ok(walker) = walkdir::WalkDir::new(path) {
            for entry in walker {
                if let Ok(entry) = entry {
                    let path = entry.path();
                    if path.extension().map_or(false, |ext| ext == "nix") {
                        if let Ok(content) = fs::read_to_string(path) {
                            match crate::fixer::fix_content(&content, &path.to_string_lossy(), args) {
                                Ok(fixed) => {
                                    if args.dry_run {
                                        show_diff(&content, &fixed, &path.to_string_lossy());
                                    } else {
                                        if let Err(e) = fs::write(path, &fixed) {
                                            eprintln!("Error writing file: {}", e);
                                        }
                                    }
                                }
                                Err(e) => eprintln!("Error: {}", e),
                            }
                        }
                    }
                }
            }
        }
    }
}

fn show_diff(original: &str, fixed: &str, filename: &str) {
    let original_lines: Vec<_> = original.lines().collect();
    let fixed_lines: Vec<_> = fixed.lines().collect();

    // Simple diff output
    println!("--- {}", filename);
    println!("+++ {} [fixed]", filename);

    // Use similar crate for diff
    let diff = similar::TextDiff::from_lines(&original, &fixed);

    let mut line_num = 1;
    for change in diff.iter_all_changes() {
        match change {
            similar::Change::Delete(line) => {
                println!("-{}", line.trim_end());
            }
            similar::Change::Insert(line) => {
                println!("+{}", line.trim_end());
            }
            similar::Change::Equal(line) => {
                // Print context lines with space prefix
                println!(" {}", line.trim_end());
            }
        }
    }
}

pub fn single_fix(args: SingleArgs) {
    // Parse position
    let parts: Vec<&str> = args.position.split(',').collect();
    if parts.len() != 2 {
