pub fn check_bool_comparison(ast: &AST, content: &str, filename: &str) -> Option<Vec<Issue>> {
    // This is a simplified implementation. A real version would need to walk the AST properly.
    let mut issues = Vec::new();

    // Simple regex-based detection for now
    let re = regex::Regex::new(r"(\w+)\s*(==|!=)\s*(true|false)").unwrap();

    for (line_num, line) in content.lines().enumerate() {
        for cap in re.captures_iter(line) {
            let full_match = cap.get(0).unwrap();
            let var_name = cap.get(1).unwrap().as_str();
            let op = cap.get(2).unwrap().as_str();
            let bool_val = cap.get(3).unwrap().as_str();

            let column = full_match.start() + 1;
            let message = if op == "==" && bool_val == "true" {
                format!("Comparing `{}` with boolean literal `{}`", var_name, bool_val)
            } else if op == "!=" && bool_val == "false" {
                format!("Comparing `{}` with boolean literal `{}`", var_name, bool_val)
            } else {
                continue;
            };

            issues.push(Issue {
                code: "W01",
                message,
                filename: filename.to_string(),
                line: line_num + 1,
                column,
                start_offset: full_match.start(),
                end_offset: full_match.end(),
            });
        }
    }

    if issues.is_empty() {
        None
    } else {
        Some(issues)
    }
}

pub fn check_empty_let_in(ast: &AST, content: &str, filename: &str) -> Option<Vec<Issue>> {
    let mut issues = Vec::new();

    // Simple regex-based detection for empty let-in
    let re = regex::Regex::new(r"let\s+in\s").unwrap();

    for (line_num, line) in content.lines().enumerate() {
        if let Some(mat) = re.find(line) {
            issues.push(Issue {
                code: "W02",
                message: "This let-in expression has no entries".to_string(),
                filename: filename.to_string(),
                line: line_num + 1,
                column: mat.start() + 1,
                start_offset: mat.start(),
                end_offset: mat.end(),
            });
        }
    }

    if issues.is_empty() {
        None
    } else {
        Some(issues)
    }
}

pub fn check_useless_parens(ast: &AST, content: &str, filename: &str) -> Option<Vec<Issue>> {
    let mut issues = Vec::new();

    // Simple regex for parens around simple expressions in bindings
    let re = regex::Regex::new(r"=\s*\(([^()]+)\);").unwrap();

    for (line_num, line) in content.lines().enumerate() {
        if let Some(mat) = re.find(line) {
            let inner = &line[mat.start() + 1..mat.end() - 2].trim();
            // Only flag if inner expression doesn't need parens
            if !inner.contains("||") && !inner.contains("&&") && !inner.contains(",") {
                issues.push(Issue {
                    code: "W08",
                    message: "Useless parentheses around value in binding".to_string(),
                    filename: filename.to_string(),
                    line: line_num + 1,
                    column: mat.start() + 1,
                    start_offset: mat.start(),
                    end_offset: mat.end(),
                });
            }
        }
    }

    if issues.is_empty() {
        None
    } else {
        Some(issues)
    }
}

pub fn check_empty_inherit(ast: &AST, content: &str, filename: &str) -> Option<Vec<Issue>> {
    let mut issues = Vec::new();

    // Find empty inherit statements
    let re = regex::Regex::new(r"\{\s*inherit\s*;\s*\}").unwrap();

    for (line_num, line) in content.lines().enumerate() {
        for mat in re.find_iter(line) {
            issues.push(Issue {
                code: "W14",
                message: "Remove this empty `inherit` statement".to_string(),
                filename: filename.to_string(),
                line: line_num + 1,
                column: mat.start() + 1,
                start_offset: mat.start(),
                end_offset: mat.end(),
            });
        }
    }

    if issues.is_empty() {
        None
    } else {
        Some(issues)
    }
}
