    let mut issues = Vec::new();

    // Simple regex-based detection for now
    let re = regex::Regex::new(r"(\w+)\s*(==|!=)\s*(true|false)").unwrap();

    for (line_num, line) in content.lines().enumerate() {
        for cap in re.captures_iter(line) {
            let full_match = cap.get(0).unwrap();
            let var_name = cap.get(1).unwrap().as_str();
            let op = cap.get(2).unwrap().as_str();
            let bool_val = cap.get(3).unwrap().as_str();

            let column = full_match.start() + 1;
            let message = if op == "==" && bool_val == "true" {
                format!("Comparing `{}` with boolean literal `{}`", var_name, bool_val)
            } else if op == "!=" && bool_val == "false" {
                format!("Comparing `{}` with boolean literal `{}`", var_name, bool_val)
            } else {
                continue;
            };

            issues.push(Issue {
                code: "W01",
                message,
                filename: filename.to_string(),
                line: line_num + 1,
                column,
                start_offset: full_match.start(),
                end_offset: full_match.end(),
            });
        }
    }

    if issues.is_empty() {
        None
    } else {
        Some(issues)
    }
