pub fn check_empty_let_in(ast: &AST, content: &str, filename: &str) -> Option<Vec<Issue>> {
    let mut issues = Vec::new();

    // Simple regex-based detection for empty let-in
    let re = regex::Regex::new(r"let\s+in\s").unwrap();

    for (line_num, line) in content.lines().enumerate() {
        if let Some(mat) = re.find(line) {
            issues.push(Issue {
