pub fn check_useless_parens(ast: &AST, content: &str, filename: &str) -> Option<Vec<Issue>> {
    let mut issues = Vec::new();

    // Simple regex for parens around simple expressions in bindings
    let re = regex::Regex::new(r"=\s*\(([^()]+)\);").unwrap();

    for (line_num, line) in content.lines().enumerate() {
        if let Some(mat) = re.find(line) {
            let inner = &line[mat.start() + 1..mat.end() - 2].trim();
            // Only flag if inner expression doesn't need parens
