pub fn check_bool_comparison(content: &str, filename: &str) -> Vec<Issue> {
    let mut issues = Vec::new();

    let lines: Vec<&str> = content.lines().collect();

    for (line_num, line) in lines.iter().enumerate() {
        let mut search_pos = 0;
        while let Some(idx) = line[search_pos..].find("==") {
            let actual_idx = search_pos + idx;

            // Get word before ==
            let before = &line[..actual_idx];
            let before_trimmed = before.trim_end();
            if before_trimmed.is_empty() {
                search_pos = actual_idx + 2;
                continue;
            }

            // Extract the last word
            let last_word_start = before_trimmed.rfind(|c: char| !c.is_alphanumeric() && c != '_').map(|i| i + 1).unwrap_or(0);
            let var_name = &before_trimmed[last_word_start..];

            // Get word after ==
            let after = &line[actual_idx + 2..];
            let after_trimmed = after.trim_start();

            if after_trimmed.starts_with("true") || after_trimmed.starts_with("false") {
                let bool_val = if after_trimmed.starts_with("true") { "true" } else { "false" };

                issues.push(Issue {
                    code: "W01",
                    message: format!("Comparing `{}` with boolean literal `{}`", var_name, bool_val),
                    filename: filename.to_string(),
                    line: line_num + 1,
                    column: var_name.len() + 1,
                    start_offset: last_word_start,
                    end_offset: actual_idx + 2 + bool_val.len(),
                    line_content: line.to_string(),
                });
                search_pos = actual_idx + 2;
            } else {
                search_pos = actual_idx + 2;
            }
        }

        // Also check for !=
        search_pos = 0;
        while let Some(idx) = line[search_pos..].find("!=") {
            let actual_idx = search_pos + idx;

            let before = &line[..actual_idx];
            let before_trimmed = before.trim_end();
            if before_trimmed.is_empty() {
                search_pos = actual_idx + 2;
                continue;
            }

            let last_word_start = before_trimmed.rfind(|c: char| !c.is_alphanumeric() && c != '_').map(|i| i + 1).unwrap_or(0);
            let var_name = &before_trimmed[last_word_start..];

            let after = &line[actual_idx + 2..];
            let after_trimmed = after.trim_start();

            if after_trimmed.starts_with("false") || after_trimmed.starts_with("true") {
                let bool_val = if after_trimmed.starts_with("true") { "true" } else { "false" };

                issues.push(Issue {
                    code: "W01",
                    message: format!("Comparing `{}` with boolean literal `{}`", var_name, bool_val),
                    filename: filename.to_string(),
                    line: line_num + 1,
                    column: var_name.len() + 1,
                    start_offset: last_word_start,
                    end_offset: actual_idx + 2 + bool_val.len(),
                    line_content: line.to_string(),
                });
                search_pos = actual_idx + 2;
            } else {
                search_pos = actual_idx + 2;
            }
        }
    }

    issues
}

pub fn check_empty_let_in(content: &str, filename: &str) -> Vec<Issue> {
    let mut issues = Vec::new();

    let lines: Vec<&str> = content.lines().collect();

    for (line_num, line) in lines.iter().enumerate() {
        if let Some(idx) = line.find("let") {
            let after = &line[idx + 3..];
            if after.trim_start().starts_with("in") {
                issues.push(Issue {
                    code: "W02",
                    message: "This let-in expression has no entries".to_string(),
                    filename: filename.to_string(),
                    line: line_num + 1,
                    column: idx + 1,
                    start_offset: idx,
                    end_offset: idx + 7,
                    line_content: line.to_string(),
                });
            }
        }
    }

    issues
}

pub fn check_useless_parens(content: &str, filename: &str) -> Vec<Issue> {
    let mut issues = Vec::new();

    let lines: Vec<&str> = content.lines().collect();

    for (line_num, line) in lines.iter().enumerate() {
        // Look for patterns like "= (something);"
        let mut search_pos = 0;
        while let Some(idx) = line[search_pos..].find('=') {
            let actual_idx = search_pos + idx;
            let after = &line[actual_idx + 1..];
            let trimmed = after.trim_start();

            if trimmed.starts_with('(') {
                // Find matching close paren
                let mut depth = 0;
                let mut close_idx = None;
                for (i, c) in trimmed[1..].chars().enumerate() {
                    if c == '(' {
                        depth += 1;
                    } else if c == ')' {
                        if depth == 0 {
                            close_idx = Some(i);
                            break;
                        }
                        depth -= 1;
                    }
                }

                if let Some(close) = close_idx {
                    let inner = &trimmed[1..close];
                    // Check if parens are actually needed
                    if !inner.contains("||") && !inner.contains("&&") && !inner.contains(",") {
                        let before_count = after.len() - trimmed.len();
                        issues.push(Issue {
                            code: "W08",
                            message: "Useless parentheses around value in binding".to_string(),
                            filename: filename.to_string(),
                            line: line_num + 1,
                            column: actual_idx + before_count + 1,
                            start_offset: actual_idx + before_count,
                            end_offset: actual_idx + before_count + close + 2,
                            line_content: line.to_string(),
                        });
                    }
                }
            }

            search_pos = actual_idx + 1;
        }
    }

    issues
}

pub fn check_empty_inherit(content: &str, filename: &str) -> Vec<Issue> {
    let mut issues = Vec::new();

    let lines: Vec<&str> = content.lines().collect();

    for (line_num, line) in lines.iter().enumerate() {
        // Look for "{ inherit; }" or similar
        let mut search_pos = 0;
        while let Some(idx) = line[search_pos..].find("inherit") {
            let actual_idx = search_pos + idx;

            // Check if followed by ; immediately (possibly with whitespace)
            let after = &line[actual_idx + 7..].trim_start();
            if after.starts_with(';') {
                issues.push(Issue {
                    code: "W14",
                    message: "Remove this empty `inherit` statement".to_string(),
                    filename: filename.to_string(),
                    line: line_num + 1,
                    column: actual_idx + 1,
                    start_offset: actual_idx,
                    end_offset: actual_idx + 7,
                    line_content: line.to_string(),
                });
            }

            search_pos = actual_idx + 1;
        }
    }

    issues
}
