use crate::cli::FixArgs;

pub fn fix_content(content: &str, _filename: &str, _args: &FixArgs) -> Result<String, String> {
    let mut result = content.to_string();

    // W01 - bool comparison
    result = result.replace(" == true", "");
    result = result.replace(" != false", "");

    // W02 - empty let-in
    let lines: Vec<&str> = result.lines().collect();
    let mut fixed_lines = Vec::new();

    for line in lines {
        let trimmed = line.trim();
        if trimmed.starts_with("let") && trimmed.ends_with("in") {
            // This is likely an empty let-in, try to remove it
            if let Some(rest) = line.strip_suffix("in") {
                // Just remove the "let" part
                if let Some(idx) = rest.find("let") {
                    let before = &rest[..idx];
                    fixed_lines.push(before.to_string());
                    continue;
                }
            }
        }
        fixed_lines.push(line.to_string());
    }

    result = fixed_lines.join("\n");

    // W08 - useless parens in bindings
    let mut output = String::new();
    for line in result.lines() {
        let mut fixed_line = line.to_string();

        // Replace "= (expr);" with "= expr;"
        if let Some(idx) = fixed_line.find("= (") {
            let after = &fixed_line[idx + 3..];
            if let Some(close_idx) = after.find(");") {
                let inner = &after[..close_idx];
                if !inner.contains("||") && !inner.contains("&&") {
                    let before = &fixed_line[..idx + 2];
                    let rest = &fixed_line[idx + 3 + close_idx + 2..];
                    fixed_line = format!("{} {}{}", before, inner, rest);
                }
            }
        }

        output.push_str(&fixed_line);
        output.push('\n');
    }

    result = output.trim_end().to_string();

    // W14 - empty inherit
    result = result.replace("{ inherit; }", "{}");

    Ok(result)
}
