use crate::cli::{CheckArgs, FixArgs};
use crate::lints;
use crate::parser;
use std::fs;
use std::io::{self, Read};
use std::path::Path;

pub fn check_stdin(args: &CheckArgs) {
    let mut content = String::new();
    io::stdin().read_to_string(&mut content).unwrap();

    check_content(&content, "<stdin>", args);
}

pub fn check_path(path: &str, args: &CheckArgs) {
    if Path::new(path).is_file() {
        match fs::read_to_string(path) {
            Ok(content) => check_content(&content, path, args),
            Err(e) => eprintln!("Error reading file {}: {}", path, e),
        }
    } else {
        // Walk directory - simple implementation
        match std::fs::read_dir(path) {
            Ok(entries) => {
                for entry in entries {
                    if let Ok(entry) = entry {
                        let path = entry.path();
                        if path.is_file() && path.extension().map_or(false, |ext| ext == "nix") {
                            if let Ok(content) = fs::read_to_string(&path) {
                                check_content(&content, &path.to_string_lossy(), args);
                            }
                        } else if path.is_dir() {
                            let mut new_args = args.clone();
                            new_args.target = path.to_string_lossy().to_string();
                            check_path(&path.to_string_lossy(), &new_args);
                        }
                    }
                }
            }
            Err(e) => eprintln!("Error reading directory {}: {}", path, e),
        }
    }
}

pub fn check_content(content: &str, filename: &str, args: &CheckArgs) {
    match parser::parse_nix(content) {
        Ok(()) => {
            let mut has_issues = false;

            // W01 - bool_comparison
            let issues = lints::check_bool_comparison(content, filename);
            for issue in issues {
                report_issue(&issue, &args.format);
                has_issues = true;
            }

            // W02 - empty_let_in
            let issues = lints::check_empty_let_in(content, filename);
            for issue in issues {
                report_issue(&issue, &args.format);
                has_issues = true;
            }

            // W08 - useless_parens
            let issues = lints::check_useless_parens(content, filename);
            for issue in issues {
                report_issue(&issue, &args.format);
                has_issues = true;
            }

            // W14 - empty_inherit
            let issues = lints::check_empty_inherit(content, filename);
            for issue in issues {
                report_issue(&issue, &args.format);
                has_issues = true;
            }

            if has_issues {
                std::process::exit(1);
            }
        }
        Err(e) => eprintln!("Error parsing {}: {}", filename, e),
    }
}

fn report_issue(issue: &lints::Issue, format: &str) {
    if format == "errfmt" {
        println!("{}>{},{}:W:{}:{}", issue.filename, issue.line, issue.column, issue.code, issue.message);
    } else {
        // stderr format with colors
        println!("{}", issue.format_for_stderr());
    }
}

pub fn fix_stdin(args: &FixArgs) {
    let mut content = String::new();
    io::stdin().read_to_string(&mut content).unwrap();

    match crate::fixer::fix_content(&content, "<stdin>", args) {
        Ok(fixed) => print!("{}", fixed),
        Err(e) => eprintln!("Error: {}", e),
    }
}

pub fn fix_path(path: &str, args: &FixArgs) {
    if Path::new(path).is_file() {
        match fs::read_to_string(path) {
            Ok(content) => {
                match crate::fixer::fix_content(&content, path, args) {
                    Ok(fixed) => {
                        if args.dry_run {
                            show_diff(&content, &fixed, path);
                        } else {
                            if let Err(e) = fs::write(path, &fixed) {
                                eprintln!("Error writing file {}: {}", path, e);
                            }
                        }
                    }
                    Err(e) => eprintln!("Error: {}", e),
                }
            }
            Err(e) => eprintln!("Error reading file {}: {}", path, e),
        }
    } else {
        // Walk directory
        if let Ok(entries) = std::fs::read_dir(path) {
            for entry in entries {
                if let Ok(entry) = entry {
                    let path = entry.path();
                    if path.is_file() && path.extension().map_or(false, |ext| ext == "nix") {
                        if let Ok(content) = fs::read_to_string(&path) {
                            match crate::fixer::fix_content(&content, &path.to_string_lossy(), args) {
                                Ok(fixed) => {
                                    if args.dry_run {
                                        show_diff(&content, &fixed, &path.to_string_lossy());
                                    } else {
                                        if let Err(e) = fs::write(&path, &fixed) {
                                            eprintln!("Error writing file: {}", e);
                                        }
                                    }
                                }
                                Err(e) => eprintln!("Error: {}", e),
                            }
                        }
                    } else if path.is_dir() {
                        let mut new_args = args.clone();
                        new_args.target = path.to_string_lossy().to_string();
                        fix_path(&path.to_string_lossy(), &new_args);
                    }
                }
            }
        }
    }
}

fn show_diff(original: &str, fixed: &str, filename: &str) {
    if original == fixed {
        return;
    }

    println!("--- {}", filename);
    println!("+++ {} [fixed]", filename);

    let original_lines: Vec<&str> = original.lines().collect();
    let fixed_lines: Vec<&str> = fixed.lines().collect();

    // Simple diff output
    let mut i = 0;
    let mut j = 0;

    while i < original_lines.len() || j < fixed_lines.len() {
        if i < original_lines.len() && j < fixed_lines.len() && original_lines[i] == fixed_lines[j] {
            println!(" {}", original_lines[i]);
            i += 1;
            j += 1;
        } else if i < original_lines.len() && (j >= fixed_lines.len() || original_lines[i] != fixed_lines.get(j).unwrap_or(&"")) {
            println!("-{}", original_lines[i]);
            i += 1;
        } else if j < fixed_lines.len() {
            println!("+{}", fixed_lines[j]);
            j += 1;
        }
    }
}
