pub fn check_useless_parens(content: &str, filename: &str) -> Vec<Issue> {
    let mut issues = Vec::new();

    let lines: Vec<&str> = content.lines().collect();

    for (line_num, line) in lines.iter().enumerate() {
        // Look for patterns like "= (something);"
        let mut search_pos = 0;
        while let Some(idx) = line[search_pos..].find('=') {
            let actual_idx = search_pos + idx;
            let after = &line[actual_idx + 1..];
            let trimmed = after.trim_start();

            if trimmed.starts_with('(') {
                // Find matching close paren
                let mut depth = 0;
                let mut close_idx = None;
                for (i, c) in trimmed[1..].chars().enumerate() {
                    if c == '(' {
                        depth += 1;
                    } else if c == ')' {
                        if depth == 0 {
                            close_idx = Some(i);
                            break;
                        }
                        depth -= 1;
                    }
                }

                if let Some(close) = close_idx {
                    let inner = &trimmed[1..close];
                    // Check if parens are actually needed
                    if !inner.contains("||") && !inner.contains("&&") && !inner.contains(",") {
                        let before_count = after.len() - trimmed.len();
                        let column = actual_idx + before_count + 1;
                        issues.push(Issue {
